-- Additional original study quizzes for remaining common and finance/project-pathway units.
-- These questions are authored for practice and are not official MUST examination questions.
WITH quiz_seed(course_code,title,description) AS (
 VALUES
 ('CIT3100','Ace Practice · Introduction to Computer Technology','Original practice on computer hardware, software, storage and basic security.'),
 ('EFN3151','Ace Practice · Sociology','Original practice on socialisation, institutions, norms and social research.'),
 ('UCU3102','Ace Practice · Communication Skills','Original practice on audience, listening, evidence and clear academic communication.'),
 ('UCU3103','Ace Practice · HIV/AIDS','Original health-education questions on transmission, prevention and treatment literacy; not personal medical advice.'),
 ('BFC3175','Ace Practice · Financial Accounting II','Original practice on inventory, receivables, accruals and cash-flow reporting.'),
 ('SMB3151','Ace Practice · Management Mathematics','Original applied practice on ratios, equations, percentages and compound interest.'),
 ('UCU3101','Ace Practice · Development Studies and Ethics','Original practice on sustainable development, accountability, ethics and evidence.'),
 ('BFB3204','Ace Practice · Business English','Original practice on audience, clarity, tone, grammar and professional reports.'),
 ('BFB3302','Ace Practice · Behavioural Science','Original practice on perception, bias, group decision-making and behaviour at work.'),
 ('BFB3465','Ace Practice · Motivation and Stress Management','Original practice on work stress, coping, burnout and supportive management.'),
 ('EMP3350','Ace Practice · Research Methodology','Original practice on research design, validity, sampling and measurement.'),
 ('BFC3381','Ace Practice · Project Appraisal','Original practice on discounted cash flows, payback and appraisal assumptions.'),
 ('BFC3479','Ace Practice · Financial Risk Management','Original practice on market, credit, liquidity and operational risk.'),
 ('BFB3361','Ace Practice · Project Risk Analysis and Management','Original practice on risk registers, responses, residual risk and monitoring.')
),
inserted_quizzes AS (
 INSERT INTO public.ace_quizzes(title,course_code,description,status)
 SELECT s.title,s.course_code,s.description,'published' FROM quiz_seed s
 WHERE NOT EXISTS(SELECT 1 FROM public.ace_quizzes q WHERE q.title=s.title AND q.course_code=s.course_code)
 RETURNING id,course_code,title
),
quiz_ids AS (
 SELECT id,course_code,title FROM inserted_quizzes
 UNION ALL
 SELECT q.id,q.course_code,q.title FROM public.ace_quizzes q JOIN quiz_seed s ON s.course_code=q.course_code AND s.title=q.title
 WHERE NOT EXISTS(SELECT 1 FROM inserted_quizzes i WHERE i.id=q.id)
),
question_seed(course_code,quiz_title,sort_order,prompt,options,correct_index,explanation) AS (
 VALUES
 -- Computer Technology
 ('CIT3100','Ace Practice · Introduction to Computer Technology',1,'Which component executes program instructions and performs arithmetic and logic operations?',ARRAY['CPU','Monitor','Keyboard','Power cable']::text[],0,'The central processing unit executes instructions and performs core processing operations.',1),
 ('CIT3100','Ace Practice · Introduction to Computer Technology',2,'Why is RAM described as volatile memory?',ARRAY['Its contents are generally lost when power is removed','It stores data permanently without power','It is always slower than every storage device','It only stores printed documents']::text[],0,'RAM is working memory whose contents generally do not persist after power is removed.',2),
 ('CIT3100','Ace Practice · Introduction to Computer Technology',3,'Compared with a traditional hard disk, a solid-state drive generally has:',ARRAY['No moving mechanical read/write parts and faster access','A need for magnetic spinning platters','No ability to store files','Only volatile memory']::text[],0,'SSDs use flash memory rather than spinning magnetic platters, usually improving access speed and shock resistance.',3),
 ('CIT3100','Ace Practice · Introduction to Computer Technology',4,'The operating system primarily:',ARRAY['Manages hardware resources and provides services for applications','Replaces every application used by the business','Guarantees that a computer cannot be attacked','Creates the business strategy automatically']::text[],0,'An operating system manages resources such as memory, processes, devices and files and provides a platform for applications.',4),
 ('CIT3100','Ace Practice · Introduction to Computer Technology',5,'An email asks an employee to urgently open an unexpected attachment and enter a password on an unfamiliar site. The safest first response is to:',ARRAY['Verify the request through a trusted channel and avoid the suspicious link or attachment','Enter the password quickly to avoid account suspension','Forward the email to all contacts','Disable security updates']::text[],0,'Urgency, unexpected attachments and credential requests are common phishing indicators; verify independently and report suspicious messages.',5),
 -- Sociology
 ('EFN3151','Ace Practice · Sociology',1,'Socialisation is the process through which people:',ARRAY['Learn and internalise norms, values and roles of their society','Inherit all behaviour genetically','Avoid interaction with other people','Stop learning after childhood']::text[],0,'Socialisation occurs throughout life as people learn social expectations, identities and ways of participating in groups.',1),
 ('EFN3151','Ace Practice · Sociology',2,'A social institution is best described as:',ARRAY['An established set of roles, norms and practices organised around important social needs','Any building with a sign outside','A single person’s temporary preference','A business invoice']::text[],0,'Institutions such as family, education, law and the economy organise recurring social relationships and expectations.',2),
 ('EFN3151','Ace Practice · Sociology',3,'A researcher observes that students with longer commutes report lower average study time. What can be concluded from this association alone?',ARRAY['The variables are associated in the observed data, but causation is not established','Long commutes definitely cause every student to study less','Study time causes every commute to be longer','No further investigation is useful']::text[],0,'An observed association may reflect confounding, selection or reverse direction; a suitable design is needed for causal claims.',3),
 ('EFN3151','Ace Practice · Sociology',4,'A social norm is:',ARRAY['A shared expectation about appropriate behaviour in a particular group or context','A law of physics','A personal goal held by exactly one person','A financial ratio']::text[],0,'Norms are social expectations that guide and regulate behaviour, although they vary across groups and contexts.',4),
 ('EFN3151','Ace Practice · Sociology',5,'Why should sociologists distinguish individual experiences from structural explanations?',ARRAY['Patterns may be shaped by institutions, resources and social arrangements as well as individual choices','Social structures never affect people','Individual decisions explain every social outcome completely','Structural explanations do not require evidence']::text[],0,'Sociological analysis considers how personal agency interacts with institutions, opportunities, constraints and wider social patterns.',5),
 -- Communication Skills
 ('UCU3102','Ace Practice · Communication Skills',1,'Before writing a report, analysing the audience helps the writer decide:',ARRAY['What the readers need to know, the appropriate detail and the most useful structure','Which facts should be hidden regardless of relevance','How to make the report as long as possible','Whether evidence is necessary']::text[],0,'Audience analysis helps determine purpose, tone, background information and organisation.',1),
 ('UCU3102','Ace Practice · Communication Skills',2,'Active listening is best demonstrated by:',ARRAY['Paying attention, clarifying meaning and summarising the speaker’s key point','Preparing a reply while ignoring the speaker','Interrupting whenever a new idea appears','Assuming silence means agreement']::text[],0,'Active listening involves attention, clarification and checking understanding rather than simply waiting to speak.',2),
 ('UCU3102','Ace Practice · Communication Skills',3,'A student paraphrases another author’s argument in different words but gives no citation. The main academic problem is:',ARRAY['Plagiarism because the source idea is unacknowledged','A correct use of evidence in all cases','A formatting issue with no academic significance','An example of primary data collection']::text[],0,'Paraphrased ideas still require attribution; changing wording does not remove the need to cite the source.',3),
 ('UCU3102','Ace Practice · Communication Skills',4,'Which sentence is the clearest professional request?',ARRAY['Please submit the revised budget by 3 p.m. on Thursday so we can review it before the meeting.','Do the thing soon because you know what I mean.','It is hereby possibly requested that action may at some time occur.','The budget, which was perhaps, and in a sense, maybe revised.']::text[],0,'The first sentence states the action, deadline and reason directly.',4),
 ('UCU3102','Ace Practice · Communication Skills',5,'Constructive feedback is most useful when it:',ARRAY['Describes specific behaviour and its impact, then suggests an actionable improvement','Labels a person as incapable','Uses vague criticism without examples','Is delivered publicly to embarrass the recipient']::text[],0,'Specific, respectful and actionable feedback helps the recipient understand what to change and why.',5),
 -- HIV/AIDS
 ('UCU3103','Ace Practice · HIV/AIDS',1,'HIV and AIDS are related but not identical because:',ARRAY['HIV is the virus; AIDS is an advanced stage of HIV infection that may develop without effective treatment','AIDS is a type of mosquito','HIV is transmitted by ordinary handshakes','Everyone with HIV immediately has AIDS']::text[],0,'HIV is the virus; AIDS describes advanced disease. Effective treatment can prevent progression.',1),
 ('UCU3103','Ace Practice · HIV/AIDS',2,'Which activity does NOT transmit HIV under ordinary circumstances?',ARRAY['Sharing a classroom or shaking hands','Sharing contaminated injecting equipment','Unprotected sexual exposure where transmission risk is present','Transmission through certain blood exposures']::text[],0,'HIV is not transmitted by casual contact such as handshakes, shared classrooms or ordinary social interaction.',2),
 ('UCU3103','Ace Practice · HIV/AIDS',3,'Why is HIV testing with informed consent and confidentiality important?',ARRAY['It supports informed decisions, trust and linkage to appropriate care','It guarantees that a person will never need follow-up','It makes prevention education unnecessary','It allows results to be disclosed publicly by default']::text[],0,'Ethical testing respects autonomy and privacy and should connect people to appropriate counselling, prevention or treatment services.',3),
 ('UCU3103','Ace Practice · HIV/AIDS',4,'Effective antiretroviral therapy can:',ARRAY['Suppress HIV replication and help people live longer, healthier lives','Remove the need for adherence or clinical follow-up','Guarantee that no other health issue can occur','Turn HIV into a bacterial infection']::text[],0,'ART suppresses viral replication and improves health outcomes; ongoing clinical care and adherence remain important.',4),
 ('UCU3103','Ace Practice · HIV/AIDS',5,'Which approach is most appropriate when discussing HIV with classmates?',ARRAY['Use evidence-based, non-stigmatising language and respect privacy','Assume a person’s status from appearance','Share someone’s private result to warn others','Treat casual contact as a transmission route']::text[],0,'Accurate information, confidentiality and non-stigmatising language support public health and human dignity.',5),
 -- Financial Accounting II
 ('BFC3175','Ace Practice · Financial Accounting II',1,'A bank reconciliation is prepared primarily to:',ARRAY['Explain differences between the bank statement and the cash-book balance and identify needed adjustments','Make the two balances agree by deleting unexplained items','Calculate depreciation on equipment','Replace all source documents']::text[],0,'Reconciliation explains timing differences and errors; only valid, supported adjustments should be recorded.',1),
 ('BFC3175','Ace Practice · Financial Accounting II',2,'If inventory cost is KSh 50,000 and its net realisable value is KSh 46,000, inventory is generally measured at:',ARRAY['KSh 46,000','KSh 50,000','KSh 96,000','Zero in every case']::text[],0,'Under the lower-of-cost-and-net-realisable-value principle, inventory is written down when NRV is below cost.',2),
 ('BFC3175','Ace Practice · Financial Accounting II',3,'A company has significant overdue receivables and evidence some customers may not pay. The most appropriate accounting response is to:',ARRAY['Assess expected credit losses and recognise an appropriate allowance under the applicable reporting framework','Assume all receivables will be collected because invoices exist','Delete every receivable immediately','Record the overdue amount as additional cash']::text[],0,'Receivables should reflect the applicable impairment/expected-credit-loss requirements and evidence available at the reporting date.',3),
 ('BFC3175','Ace Practice · Financial Accounting II',4,'An expense has been incurred before year-end but the supplier invoice will arrive next month. Under accrual accounting the business should generally:',ARRAY['Recognise the expense and a corresponding accrual liability if the obligation can be estimated reliably','Wait until cash is paid in every circumstance','Record revenue instead','Ignore the expense because no invoice exists yet']::text[],0,'Accrual accounting recognises expenses when incurred, subject to the applicable recognition criteria, even if invoicing/payment occurs later.',4),
 ('BFC3175','Ace Practice · Financial Accounting II',5,'A statement of cash flows helps users assess:',ARRAY['Cash generated and used by operating, investing and financing activities','Only the market price of shares','Only the value of unpaid invoices','Whether every transaction was ethical']::text[],0,'Cash-flow reporting classifies cash movements into operating, investing and financing activities to aid liquidity and financial assessment.',5),
 -- Management Mathematics
 ('SMB3151','Ace Practice · Management Mathematics',1,'A business borrows KSh 10,000 at 10% annual compound interest for two years. Ignoring fees, the amount due after two years is:',ARRAY['KSh 11,000','KSh 12,000','KSh 12,100','KSh 20,000']::text[],2,'Compound amount = 10,000 × 1.10² = KSh 12,100.',1),
 ('SMB3151','Ace Practice · Management Mathematics',2,'If total cost is C = 5,000 + 200q, what is the total cost when output q is 30 units?',ARRAY['KSh 6,000','KSh 11,000','KSh 5,200','KSh 200']::text[],1,'Substitute q = 30: 5,000 + 6,000 = KSh 11,000.',2),
 ('SMB3151','Ace Practice · Management Mathematics',3,'A ratio of 3:5 has a total of 64 units. The smaller share is:',ARRAY['16','24','32','40']::text[],1,'There are 8 total parts; each part is 64 ÷ 8 = 8, so the smaller share is 3 × 8 = 24.',3),
 ('SMB3151','Ace Practice · Management Mathematics',4,'A price falls from KSh 800 to KSh 680. The percentage decrease is:',ARRAY['10%','12%','15%','20%']::text[],2,'Decrease = 120; percentage decrease = 120 ÷ 800 × 100 = 15%.',4),
 ('SMB3151','Ace Practice · Management Mathematics',5,'A firm’s sales increase by 20% from KSh 250,000. New sales are:',ARRAY['KSh 270,000','KSh 300,000','KSh 320,000','KSh 500,000']::text[],1,'A 20% increase is 250,000 × 1.20 = KSh 300,000.',5),
 -- Development Studies and Ethics
 ('UCU3101','Ace Practice · Development Studies and Ethics',1,'Sustainable development is commonly concerned with:',ARRAY['Meeting present needs while preserving the ability of future generations to meet theirs','Maximising current output regardless of long-term harm','Economic growth alone with no social or environmental consideration','Avoiding all technological change']::text[],0,'The concept connects present well-being with long-term environmental, social and economic sustainability.',1),
 ('UCU3101','Ace Practice · Development Studies and Ethics',2,'An ethical decision process is strengthened by:',ARRAY['Identifying affected stakeholders, considering alternatives and explaining the reasons for a decision','Selecting the option that benefits the decision-maker in every case','Ignoring foreseeable harms','Replacing evidence with rumours']::text[],0,'Structured ethical reasoning makes impacts, competing values and justification explicit.',2),
 ('UCU3101','Ace Practice · Development Studies and Ethics',3,'A development indicator should be interpreted carefully because:',ARRAY['A single measure may not capture distribution, quality of life or all dimensions of development','Every indicator measures all aspects of well-being perfectly','Indicators cannot be compared over time','Data definitions never change']::text[],0,'Development is multidimensional; indicators have definitions, limitations and distributional implications.',3),
 ('UCU3101','Ace Practice · Development Studies and Ethics',4,'Public accountability is strengthened when institutions:',ARRAY['Explain decisions, publish relevant information and provide channels for scrutiny and remedy','Make decisions without records','Prevent lawful scrutiny','Disclose private personal data without justification']::text[],0,'Accountability depends on answerability, transparency, oversight and mechanisms to address failures.',4),
 ('UCU3101','Ace Practice · Development Studies and Ethics',5,'The Sustainable Development Goals are best understood as:',ARRAY['A shared international framework of interconnected social, economic and environmental goals','A Kenyan tax statute','A guarantee that every country has identical outcomes','A replacement for all national policy choices']::text[],0,'The SDGs provide a common framework, while implementation depends on national and local context.',5),
 -- Business English
 ('BFB3204','Ace Practice · Business English',1,'A professional email subject line should generally:',ARRAY['Summarise the purpose clearly and specifically','Be left blank regardless of context','Use an unrelated joke','Contain the entire email in uppercase']::text[],0,'A concise, informative subject helps the recipient understand the message and prioritise it.',1),
 ('BFB3204','Ace Practice · Business English',2,'Which sentence uses the most appropriate formal tone?',ARRAY['Please confirm receipt of the attached report by Friday.','Hey, check this thing whenever.','You people must do what I said now.','I am like sending a report kind of.']::text[],0,'The first sentence is clear, respectful and gives an actionable deadline.',2),
 ('BFB3204','Ace Practice · Business English',3,'A report executive summary should primarily:',ARRAY['Present the purpose, key findings and recommendations briefly for decision-makers','Introduce every minor detail before stating the problem','Replace evidence with promotional claims','Include conclusions that are not supported by the report']::text[],0,'An executive summary gives readers the essential message and decisions without requiring them to read every detail first.',3),
 ('BFB3204','Ace Practice · Business English',4,'Which practice best improves clarity in a long business report?',ARRAY['Use informative headings, logical sections and concise paragraphs','Combine every idea into one very long sentence','Use unexplained acronyms throughout','Repeat the same conclusion in every section']::text[],0,'Clear structure and concise paragraphs make complex information easier to navigate and understand.',4),
 ('BFB3204','Ace Practice · Business English',5,'When quoting a source directly in an academic report, the writer should:',ARRAY['Use quotation formatting as required and provide a proper citation','Change two words and remove the citation','Present the quote as personal research','Cite only if the source is a book']::text[],0,'Direct quotations require clear attribution under the required citation style; paraphrased ideas also need citations.',5),
 -- Behavioural Science
 ('BFB3302','Ace Practice · Behavioural Science',1,'Confirmation bias occurs when a person:',ARRAY['Gives disproportionate weight to evidence that supports existing beliefs','Changes a view after carefully reviewing contrary evidence','Randomly selects data without any preference','Uses a pre-registered research design']::text[],0,'Confirmation bias favours information that supports prior beliefs and discounts conflicting evidence.',1),
 ('BFB3302','Ace Practice · Behavioural Science',2,'Groupthink is most likely when a group:',ARRAY['Suppresses disagreement in pursuit of apparent consensus','Welcomes dissent and tests assumptions','Uses independent reviews before deciding','Documents competing alternatives']::text[],0,'Groupthink occurs when pressure for consensus undermines critical evaluation of alternatives.',2),
 ('BFB3302','Ace Practice · Behavioural Science',3,'Positive reinforcement increases a behaviour by:',ARRAY['Providing a consequence that makes the behaviour more likely to recur','Removing every possible goal','Punishing all attempts','Changing the employee’s job title only']::text[],0,'Positive reinforcement adds a valued consequence after a behaviour, increasing the likelihood it recurs.',3),
 ('BFB3302','Ace Practice · Behavioural Science',4,'A manager assumes a quiet employee has no ideas without asking for input. This is primarily an example of:',ARRAY['An inference that may be biased by limited observation','A validated performance measure','A controlled experiment','A financial audit']::text[],0,'Behaviour cannot reliably be inferred from one surface cue; structured evidence and direct communication reduce bias.',4),
 ('BFB3302','Ace Practice · Behavioural Science',5,'A team makes better decisions when members:',ARRAY['Can raise concerns, examine evidence and challenge assumptions respectfully','Must agree with the most senior person','Avoid documenting options','Treat confidence as proof of accuracy']::text[],0,'Constructive dissent and evidence-based evaluation help teams identify blind spots and improve decisions.',5),
 -- Motivation and Stress Management
 ('BFB3465','Ace Practice · Motivation and Stress Management',1,'Burnout is most closely associated with:',ARRAY['Chronic workplace stress that has not been successfully managed','A single enjoyable challenge','Every short period of tiredness','A guaranteed increase in performance']::text[],0,'Burnout is associated with chronic workplace stress and can involve exhaustion, cynicism or detachment and reduced professional efficacy.',1),
 ('BFB3465','Ace Practice · Motivation and Stress Management',2,'Which response best addresses a workload problem that affects an entire team?',ARRAY['Review workload, staffing, priorities and control over work rather than relying only on individual coping tips','Tell everyone to ignore the workload','Remove breaks and support','Treat stress as proof of poor character']::text[],0,'Organisational causes often require workload and job-design changes alongside appropriate individual support.',2),
 ('BFB3465','Ace Practice · Motivation and Stress Management',3,'Psychological safety means team members can generally:',ARRAY['Ask questions, raise concerns and admit mistakes without unreasonable interpersonal punishment','Ignore agreed standards','Avoid accountability for every outcome','Make confidential information public']::text[],0,'Psychological safety supports interpersonal risk-taking and learning while preserving appropriate accountability.',3),
 ('BFB3465','Ace Practice · Motivation and Stress Management',4,'Which statement about stress is most accurate?',ARRAY['Its effects depend on intensity, duration, context and available resources','All stress is always beneficial','Stress affects only physical health','A single technique eliminates every source of stress']::text[],0,'Stress responses vary; prolonged high demands with insufficient resources can harm health and performance.',4),
 ('BFB3465','Ace Practice · Motivation and Stress Management',5,'A manager notices sustained distress and declining performance in a staff member. A responsible first approach is to:',ARRAY['Have a private, supportive conversation about work factors and appropriate support options','Publicly diagnose the person','Share the person’s health details with the whole team','Assume the cause without listening']::text[],0,'A respectful private conversation can identify work-related factors and discuss appropriate support without making an unsupported diagnosis.',5),
 -- Research Methodology
 ('EMP3350','Ace Practice · Research Methodology',1,'Reliability of a measurement tool primarily concerns whether it:',ARRAY['Produces consistent results under comparable conditions','Measures the intended construct perfectly by definition','Proves a causal relationship','Eliminates the need for sampling']::text[],0,'Reliability concerns consistency; validity concerns whether the tool measures what it is intended to measure.',1),
 ('EMP3350','Ace Practice · Research Methodology',2,'Operationalising a concept means:',ARRAY['Defining how an abstract concept will be observed or measured in the study','Removing it from the research question','Selecting results before collecting data','Using a broad term without a definition']::text[],0,'Operational definitions specify observable indicators or procedures for measuring a concept.',2),
 ('EMP3350','Ace Practice · Research Methodology',3,'A pilot study is useful because it can:',ARRAY['Reveal unclear questions, timing problems and weaknesses in study procedures before the main study','Guarantee that the final results support the hypothesis','Replace all ethical review','Make the sample automatically representative']::text[],0,'Piloting helps test feasibility and refine instruments and procedures before full data collection.',3),
 ('EMP3350','Ace Practice · Research Methodology',4,'Which is a probability sampling method?',ARRAY['Simple random sampling from a defined sampling frame','Interviewing only friends who are available','Selecting only volunteers who agree with the researcher','Choosing participants based on convenience alone']::text[],0,'Probability sampling uses a known random selection mechanism for units in the sampling frame.',4),
 ('EMP3350','Ace Practice · Research Methodology',5,'A researcher changes the hypothesis after seeing results but reports it as if it were specified beforehand. This threatens:',ARRAY['Transparency and the credibility of the research process','The arithmetic of every calculation','The need for any literature review','The definition of the study population only']::text[],0,'Undisclosed post-hoc changes can misrepresent how the study was planned and inflate confidence in findings.',5),
 -- Project Appraisal
 ('BFC3381','Ace Practice · Project Appraisal',1,'A project has a positive net present value under reasonable assumptions. This generally indicates that:',ARRAY['The present value of expected net cash flows exceeds the investment cost','The project has no risk','The payback period must be shortest in the market','The accounting profit is guaranteed']::text[],0,'Positive NPV means discounted expected net cash flows exceed the investment cost under the assumptions used.',1),
 ('BFC3381','Ace Practice · Project Appraisal',2,'A key limitation of the simple payback method is that it generally:',ARRAY['Ignores cash flows after the payback point and does not discount cash flows','Always includes all cash flows over the project life','Measures social benefits perfectly','Guarantees value maximisation']::text[],0,'Simple payback is easy to interpret but ignores later cash flows and, in its basic form, the time value of money.',2),
 ('BFC3381','Ace Practice · Project Appraisal',3,'If the discount rate rises while a project’s future cash flows remain unchanged, its NPV will generally:',ARRAY['Fall','Rise in every case','Remain unchanged for all projects','Become equal to revenue']::text[],0,'A higher discount rate lowers the present value of future cash flows, reducing NPV, all else equal.',3),
 ('BFC3381','Ace Practice · Project Appraisal',4,'Sensitivity analysis is used to:',ARRAY['Test how appraisal results change when key assumptions vary','Prove that forecasts cannot be wrong','Replace the business case with a slogan','Remove uncertainty from future cash flows']::text[],0,'Sensitivity analysis identifies which assumptions materially affect outcomes and where further evidence or risk controls may be useful.',4),
 ('BFC3381','Ace Practice · Project Appraisal',5,'A project generates private profit but causes substantial unpriced environmental harm. A social cost-benefit analysis should:',ARRAY['Consider relevant external costs and benefits in addition to private cash flows','Ignore all impacts outside the company','Assume the private NPV equals social value','Count every externality as zero unless it has an invoice']::text[],0,'Social appraisal considers effects on society, including material externalities not reflected in market prices.',5),
 -- Financial Risk Management
 ('BFC3479','Ace Practice · Financial Risk Management',1,'Credit risk is the risk that:',ARRAY['A borrower or counterparty fails to meet an agreed obligation','Market prices never change','A system has too much storage','Cash is always available at zero cost']::text[],0,'Credit risk concerns default or deterioration in the creditworthiness of a borrower or counterparty.',1),
 ('BFC3479','Ace Practice · Financial Risk Management',2,'Liquidity risk can arise when a firm:',ARRAY['Cannot meet obligations when due or cannot sell assets quickly without a substantial loss','Earns a profit in its income statement','Has a written risk policy','Uses more than one bank']::text[],0,'Liquidity risk concerns the ability to meet cash obligations or convert assets to cash without unacceptable loss.',2),
 ('BFC3479','Ace Practice · Financial Risk Management',3,'A derivative used to offset an existing exposure is primarily being used for:',ARRAY['Hedging','Accounting depreciation','Recruitment','Inventory classification']::text[],0,'Hedging uses a financial instrument to reduce an existing risk exposure, though the hedge may be imperfect or costly.',3),
 ('BFC3479','Ace Practice · Financial Risk Management',4,'Value at Risk (VaR) should not be interpreted as:',ARRAY['A guarantee that losses cannot exceed the stated amount','A model-based estimate of loss at a specified confidence level and horizon','A measure dependent on assumptions and data','A tool that should be complemented by stress testing']::text[],0,'VaR does not cap possible losses; model assumptions and tail events mean stress tests and other measures remain important.',4),
 ('BFC3479','Ace Practice · Financial Risk Management',5,'Diversification is least effective at reducing risk when asset returns:',ARRAY['Become highly positively correlated during a market stress event','Have different risk drivers','Are not perfectly correlated','Respond differently to economic conditions']::text[],0,'Correlations can rise during stress, weakening diversification precisely when protection is most needed.',5),
 -- Project Risk Analysis and Management
 ('BFB3361','Ace Practice · Project Risk Analysis and Management',1,'A project risk register should normally include:',ARRAY['Risk description, likelihood/impact, owner, response and review status','Only the project title','Only risks that have already happened','Personal opinions without assigned follow-up']::text[],0,'A risk register records uncertainty, assessment, ownership, responses and monitoring so risks can be managed systematically.',1),
 ('BFB3361','Ace Practice · Project Risk Analysis and Management',2,'Risk mitigation differs from risk transfer because mitigation aims to:',ARRAY['Reduce the likelihood or impact, while transfer allocates specified consequences to another party','Guarantee that a risk can never happen','Remove the need for contracts','Ensure every risk is accepted']::text[],0,'Mitigation changes likelihood or consequence; transfer shifts some financial or contractual exposure, but does not eliminate all accountability.',2),
 ('BFB3361','Ace Practice · Project Risk Analysis and Management',3,'After a mitigation action is implemented, risk remaining is called:',ARRAY['Residual risk','A guaranteed benefit','A sunk cost','A scope statement']::text[],0,'Residual risk is the exposure remaining after planned responses or controls are applied.',3),
 ('BFB3361','Ace Practice · Project Risk Analysis and Management',4,'A risk owner is responsible for:',ARRAY['Monitoring the assigned risk and coordinating the agreed response','Guaranteeing that no uncertainty exists','Approving every unrelated project expense','Replacing the project sponsor in all decisions']::text[],0,'A named risk owner helps ensure that assessment, response actions and follow-up have clear accountability.',4),
 ('BFB3361','Ace Practice · Project Risk Analysis and Management',5,'A project team identifies a low-probability event that could cause catastrophic harm. The best assessment approach is to:',ARRAY['Consider both likelihood and consequence and escalate according to the risk framework','Ignore it because probability is low','Rank it only by cost of the first response','Wait until the event occurs before recording it']::text[],0,'Risk priority depends on both probability and consequence; low-probability, high-impact events may require significant controls and escalation.',5)
),
questions_added AS (
 INSERT INTO public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order)
 SELECT q.id,qs.prompt,to_jsonb(qs.options),qs.correct_index,qs.explanation,qs.sort_order
 FROM question_seed qs JOIN quiz_ids q ON q.course_code=qs.course_code AND q.title=qs.quiz_title
 WHERE NOT EXISTS(SELECT 1 FROM public.ace_questions existing WHERE existing.quiz_id=q.id)
 RETURNING id
)
SELECT (SELECT count(*) FROM inserted_quizzes) quizzes_created,
       (SELECT count(*) FROM questions_added) questions_created;